@media (max-width: 767px) {
  .rooms-table thead {
    position: absolute;
    width: 1px;
    height: 1px;
    overflow: hidden;
    clip-path: inset(50%);
  }

  .rooms-table,
  .rooms-table tbody {
    display: block;
  }

  .room-row {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: var(--space-1) var(--space-3);
    margin-bottom: var(--space-2);
    padding: var(--space-3) var(--space-4);
    border: 1px solid var(--room-row-border);
    border-radius: var(--room-row-radius);
    background: var(--room-row-background);
  }

  .room-row.is-closed {
    background: var(--slot-closed-background);
    color: var(--slot-closed-foreground);
  }

  .room-row td,
  .room-row td:first-child,
  .room-row td:last-child {
    display: block;
    height: auto;
    padding: 0;
    border: 0;
    border-radius: 0;
    background: transparent;
  }

  .room-row.is-closed td {
    background: transparent;
  }

  .room-name {
    flex: 1 1 0;
    order: 1;
    min-width: 0;
  }

  .room-status {
    order: 2;
  }

  .room-capacity {
    flex-basis: 100%;
    order: 3;
    color: var(--color-ink-muted);
    font-size: var(--font-meta-size);
    line-height: var(--font-meta-line-height);
  }

  .room-capacity::before {
    content: attr(data-label) " ";
  }

  .room-row.is-closed .room-capacity {
    color: inherit;
  }

  .room-row td[colspan] {
    flex-basis: 100%;
  }

  .room-row td.room-actions {
    display: flex;
    flex-basis: 100%;
    order: 4;
    gap: var(--space-2);
    margin-top: var(--space-2);
    text-align: left;
  }

  .room-actions > * + * {
    margin-left: 0;
  }
